   1: // ============================================================
   2: // Core Types for Claude Code Replica
   3: // ============================================================
   4: 
   5: // --- Messages (Internal Format) ---
   6: 
   7: export type Message =
   8:   | UserMessage
   9:   | AssistantMessage
  10:   | ToolResultMessage
  11:   | SystemMessage;
  12: 
  13: export interface UserMessage {
  14:   role: "user";
  15:   content: ContentBlock[];
  16: }
  17: 
  18: export interface AssistantMessage {
  19:   role: "assistant";
  20:   content: string | null;
  21:   tool_calls?: ToolCall[];
  22: }
  23: 
  24: export interface ToolResultMessage {
  25:   role: "tool";
  26:   tool_call_id: string;
  27:   name?: string;
  28:   content: string;
  29: }
  30: 
  31: export interface SystemMessage {
  32:   role: "system";
  33:   content: string;
  34: }
  35: 
  36: // --- Content Blocks ---
  37: 
  38: export type ContentBlock = TextContent | ImageContent;
  39: 
  40: export interface TextContent {
  41:   type: "text";
  42:   text: string;
  43: }
  44: 
  45: export interface ImageContent {
  46:   type: "image";
  47:   source: {
  48:     type: "base64" | "url";
  49:     media_type: string;
  50:     data?: string;
  51:     url?: string;
  52:   };
  53: }
  54: 
  55: // --- Tool Calls ---
  56: 
  57: export interface ToolCall {
  58:   id: string;
  59:   type: "function";
  60:   function: {
  61:     name: string;
  62:     arguments: string; // JSON string
  63:   };
  64: }
  65: 
  66: // --- Tool System ---
  67: 
  68: export interface ToolInput {
  69:   [key: string]: unknown;
  70: }
  71: 
  72: export interface ToolResult {
  73:   content: string;
  74:   error?: string;
  75:   truncated?: boolean;
  76:   metadata?: ToolResultMetadata;
  77: }
  78: 
  79: export interface ToolResultMetadata {
  80:   durationMs?: number;
  81:   linesRead?: number;
  82:   fileSize?: number;
  83:   exitCode?: number;
  84: }
  85: 
  86: export interface ToolContext {
  87:   workspaceRoot: string;
  88:   sessionId: string;
  89:   permissionMode: PermissionMode;
  90:   /** Optional: model config for sub-agents (Task tool) */
  91:   modelConfig?: ModelConfig;
  92: }
  93: 
  94: export type PermissionMode =
  95:   | "default"
  96:   | "acceptEdits"
  97:   | "bypassPermissions"
  98:   | "plan";
  99: 
 100: export type PermissionResult =
 101:   | { allowed: true }
 102:   | { allowed: false; reason: string };
 103: 
 104: export interface Tool<T extends ToolInput = ToolInput> {
 105:   /** Unique tool name */
 106:   name: string;
 107:   /** Human-readable description */
 108:   description: string;
 109:   /** Description for the LLM system prompt */
 110:   promptDescription: string;
 111:   /** JSON Schema for input validation */
 112:   inputSchema: {
 113:     type: "object";
 114:     properties: Record<
 115:       string,
 116:       { type: string; description: string; enum?: string[]; default?: unknown }
 117:     >;
 118:     required: string[];
 119:   };
 120:   /** Whether this tool is currently enabled */
 121:   isEnabled(): boolean;
 122:   /** Whether this tool only reads (auto-approved) */
 123:   isReadOnly(): boolean;
 124:   /** Whether this tool can run concurrently */
 125:   isConcurrencySafe(): boolean;
 126:   /** Main execution */
 127:   call(input: T, context: ToolContext): Promise<ToolResult>;
 128:   /** Permission check */
 129:   checkPermissions(
 130:     input: T,
 131:     context: ToolContext,
 132:   ): Promise<PermissionResult>;
 133:   /** Format result for LLM */
 134:   formatResult(result: ToolResult): string;
 135: }
 136: 
 137: // --- Model Config ---
 138: 
 139: export interface ModelConfig {
 140:   provider: "openai" | "deepseek" | "qwen" | "moonshot" | "zhipu" | "custom";
 141:   model: string;
 142:   apiKey: string;
 143:   baseURL?: string;
 144:   maxTokens?: number;
 145:   temperature?: number;
 146:   options?: Record<string, unknown>;
 147: }
 148: 
 149: // --- Stream Events ---
 150: 
 151: export type StreamEvent =
 152:   | { type: "text_delta"; delta: string }
 153:   | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 154:   | { type: "thinking"; delta?: string }
 155:   | {
 156:       type: "done";
 157:       usage: { input_tokens: number; output_tokens: number };
 158:       finish_reason: string;
 159:     }
 160:   | { type: "error"; error: Error };
 161: 
 162: // --- Agent Loop ---
 163: 
 164: export type LoopEvent =
 165:   | { type: "text_delta"; delta: string }
 166:   | { type: "tool_use"; name: string; input: Record<string, unknown> }
 167:   | { type: "tool_results"; results: ToolExecutionResult[] }
 168:   | { type: "thinking" }
 169:   | { type: "compacting" }
 170:   | { type: "compacted"; summary: string }
 171:   | {
 172:       type: "usage";
 173:       usage: { input_tokens: number; output_tokens: number };
 174:     }
 175:   | { type: "error"; error: unknown }
 176:   | {
 177:       type: "done";
 178:       finishReason: "end_turn" | "max_turns";
 179:       turns: number;
 180:       message?: string;
 181:     }
 182:   | { type: "aborted"; reason: string };
 183: 
 184: export interface ToolExecutionResult {
 185:   toolName: string;
 186:   result?: ToolResult;
 187:   error?: string;
 188:   formatted: string;
 189:   durationMs?: number;
 190: }
 191: 
 192: export interface LoopOptions {
 193:   maxTurns?: number;
 194:   autoCompactThreshold?: number;
 195:   systemPrompt: string;
 196:   abortSignal?: AbortSignal;
 197:   /** Partial context to thread into each tool call (sessionId, workspaceRoot, permissionMode). */
 198:   toolContext?: Partial<ToolContext>;
 199:   /** Callback to prompt the user when a tool requires confirmation. */
 200:   askUser?: AskUserFn;
 201: }
 202: 
 203: /** Prompts the user to approve a destructive/dangerous tool call. */
 204: export type AskUserFn = (
 205:   tool: Tool,
 206:   input: Record<string, unknown>,
 207:   riskHint?: string,
 208: ) => Promise<boolean>;
 209: 
 210: // --- Model Caller ---
 211: 
 212: export type ModelCaller = (
 213:   messages: Message[],
 214:   tools: Tool[],
 215:   systemPrompt: string,
 216:   config: ModelConfig,
 217: ) => AsyncGenerator<StreamEvent>;
