   1: #!/usr/bin/env node
   2: // ============================================================
   3: // Claude Code Replica — CLI Entry Point
   4: // ============================================================
   5: 
   6: import * as fs from "node:fs";
   7: import * as path from "node:path";
   8: import * as crypto from "node:crypto";
   9: import * as readline from "node:readline";
  10: import dotenv from "dotenv";
  11: import chalk from "chalk";
  12: 
  13: import { agentLoop } from "./agent-loop.js";
  14: import { buildSystemPrompt } from "./system-prompt.js";
  15: import { ToolRegistry } from "./tool-registry.js";
  16: import { CORE_TOOLS } from "./tools.js";
  17: import { MCPManager, discoverMCPConfigs } from "./mcp.js";
  18: import { createModelCaller, resolveProviderConfig } from "./llm-adapter.js";
  19: import { PersistenceManager } from "./persistence.js";
  20: import type {
  21:   AskUserFn,
  22:   Message,
  23:   ModelConfig,
  24:   PermissionMode,
  25:   Tool,
  26: } from "./types.js";
  27: 
  28: // Load environment variables
  29: dotenv.config();
  30: 
  31: // --- Configuration ---
  32: 
  33: function loadConfig(): ModelConfig {
  34:   const provider = (process.env.LLM_PROVIDER || "openai") as ModelConfig["provider"];
  35:   const apiKey = process.env.LLM_API_KEY;
  36: 
  37:   if (!apiKey) {
  38:     console.error(
  39:       "Error: LLM_API_KEY is not set. Create a .env file or set the environment variable.",
  40:     );
  41:     process.exit(1);
  42:   }
  43: 
  44:   return resolveProviderConfig({
  45:     provider,
  46:     apiKey,
  47:     model: process.env.LLM_MODEL || undefined,
  48:     baseURL: process.env.LLM_BASE_URL || undefined,
  49:     maxTokens: process.env.LLM_MAX_TOKENS
  50:       ? parseInt(process.env.LLM_MAX_TOKENS)
  51:       : undefined,
  52:     temperature: process.env.LLM_TEMPERATURE
  53:       ? parseFloat(process.env.LLM_TEMPERATURE)
  54:       : undefined,
  55:   });
  56: }
  57: 
  58: // --- Workspace ---
  59: 
  60: function getWorkspaceRoot(): string {
  61:   return process.env.WORKSPACE_ROOT || process.cwd();
  62: }
  63: 
  64: const VALID_PERMISSION_MODES: PermissionMode[] = [
  65:   "default",
  66:   "acceptEdits",
  67:   "bypassPermissions",
  68:   "plan",
  69: ];
  70: 
  71: function getPermissionMode(): PermissionMode {
  72:   const mode = process.env.PERMISSION_MODE as PermissionMode | undefined;
  73:   if (mode && VALID_PERMISSION_MODES.includes(mode)) {
  74:     return mode;
  75:   }
  76:   return "default";
  77: }
  78: 
  79: // --- Load CLAUDE.md ---
  80: 
  81: function loadClaudeMd(workspaceRoot: string): string | undefined {
  82:   const claudeMdPath = path.join(workspaceRoot, "CLAUDE.md");
  83:   try {
  84:     return fs.readFileSync(claudeMdPath, "utf-8");
  85:   } catch {
  86:     return undefined;
  87:   }
  88: }
  89: 
  90: // --- Main ---
  91: 
  92: async function main() {
  93:   console.log("╔══════════════════════════════════════╗");
  94:   console.log("║   Claude Code Replica — v1.0.0      ║");
  95:   console.log("║   Local AI Coding Assistant         ║");
  96:   console.log("╚══════════════════════════════════════╝");
  97:   console.log("");
  98: 
  99:   // Load configuration
 100:   const modelConfig = loadConfig();
 101:   const workspaceRoot = getWorkspaceRoot();
 102:   const permissionMode = getPermissionMode();
 103:   const claudeMdContent = loadClaudeMd(workspaceRoot);
 104: 
 105:   console.log(`Provider: ${modelConfig.provider}`);
 106:   console.log(`Model:    ${modelConfig.model}`);
 107:   console.log(`Workspace: ${workspaceRoot}`);
 108:   console.log(`Permission mode: ${permissionMode}`);
 109:   console.log("");
 110: 
 111:   // --- Persistence ---
 112: 
 113:   const messages: Message[] = [];
 114:   const persistence = new PersistenceManager(workspaceRoot);
 115: 
 116:   // Parse --session from CLI args
 117:   const sessionArg = process.argv.find((a) => a.startsWith("--session="));
 118:   let sessionId = sessionArg?.split("=")[1];
 119: 
 120:   // If no session specified, list available ones
 121:   if (!sessionId) {
 122:     const sessions = await persistence.listSessions();
 123:     const incomplete = sessions.filter((s) => !s.completed);
 124:     if (incomplete.length > 0) {
 125:       console.log("Recent incomplete sessions:");
 126:       for (const s of incomplete.slice(0, 5)) {
 127:         console.log(
 128:           `  ${s.sessionId.slice(0, 8)}... — ${s.messageCount} msgs — ${new Date(s.updatedAt).toLocaleString()}`,
 129:         );
 130:       }
 131:       console.log(
 132:         '  Use --session=<id> to resume, or continue for a new session.',
 133:       );
 134:       console.log("");
 135:     }
 136:   }
 137: 
 138:   // Generate or resume session
 139:   if (sessionId) {
 140:     const existing = await persistence.load(sessionId);
 141:     if (existing) {
 142:       messages.push(...existing.messages);
 143:       console.log(
 144:         `Resumed session ${sessionId.slice(0, 8)}... (${existing.messageCount} messages)`,
 145:       );
 146:     } else {
 147:       console.log(
 148:         `Session ${sessionId.slice(0, 8)}... not found. Starting new session.`,
 149:       );
 150:       sessionId = persistence.generateId();
 151:     }
 152:   } else {
 153:     sessionId = persistence.generateId();
 154:   }
 155:   console.log(`Session: ${sessionId.slice(0, 8)}...`);
 156:   console.log("");
 157: 
 158:   // --- Tool Setup ---
 159: 
 160:   const toolRegistry = new ToolRegistry();
 161:   for (const tool of CORE_TOOLS) {
 162:     toolRegistry.register(tool);
 163:   }
 164: 
 165:   // MCP Setup
 166:   const mcpManager = new MCPManager();
 167:   const mcpConfigs = discoverMCPConfigs(workspaceRoot);
 168:   for (const configPath of mcpConfigs) {
 169:     await mcpManager.loadConfig(configPath);
 170:   }
 171:   for (const mcpTool of mcpManager.getAllTools()) {
 172:     toolRegistry.register(mcpTool);
 173:   }
 174: 
 175:   console.log(`Tools loaded: ${toolRegistry.enabledCount}`);
 176:   if (mcpManager.serverCount > 0) {
 177:     console.log(`MCP servers:  ${mcpManager.serverCount}`);
 178:   }
 179:   console.log("");
 180: 
 181:   // --- System Prompt ---
 182: 
 183:   const systemPrompt = buildSystemPrompt({
 184:     workspaceRoot,
 185:     tools: toolRegistry.getEnabledTools(),
 186:     claudeMdContent,
 187:   });
 188: 
 189:   // --- Model Caller ---
 190: 
 191:   const callModel = createModelCaller(modelConfig);
 192: 
 193:   // --- Conversation ---
 194: 
 195:   const tools = toolRegistry.getEnabledTools();
 196: 
 197:   // --- REPL ---
 198: 
 199:   const rl = readline.createInterface({
 200:     input: process.stdin,
 201:     output: process.stdout,
 202:   });
 203: 
 204:   const askQuestion = (prompt: string): Promise<string> => {
 205:     return new Promise((resolve) => {
 206:       rl.question(prompt, (answer) => {
 207:         resolve(answer);
 208:       });
 209:     });
 210:   };
 211: 
 212:   // Permission prompt callback. Reuses the same readline interface; during a
 213:   // loop the main REPL is awaiting, so there's no stdin contention.
 214:   const askUser: AskUserFn = async (tool, input, riskHint) => {
 215:     console.log("");
 216:     console.log(chalk.yellow(`  ⚠️  Permission required: ${tool.name}`));
 217:     if (riskHint) {
 218:       console.log(chalk.yellow(`     Risk: ${riskHint}`));
 219:     }
 220:     // Show the most relevant argument for the action.
 221:     const detail =
 222:       (typeof input.command === "string" && input.command) ||
 223:       (typeof input.filePath === "string" && input.filePath) ||
 224:       "";
 225:     if (detail) {
 226:       console.log(chalk.gray(`     ${detail}`));
 227:     }
 228:     const answer = (await askQuestion("     Allow? [y/N] ")).trim().toLowerCase();
 229:     return answer === "y" || answer === "yes";
 230:   };
 231: 
 232:   console.log('Type your request (or "exit" to quit):\n');
 233: 
 234:   // eslint-disable-next-line no-constant-condition
 235:   while (true) {
 236:     const userInput = await askQuestion("\n> ");
 237: 
 238:     if (!userInput.trim()) continue;
 239:     if (userInput.toLowerCase() === "exit") break;
 240: 
 241:     // Add user message
 242:     messages.push({
 243:       role: "user",
 244:       content: [{ type: "text", text: userInput }],
 245:     });
 246: 
 247:     // Per-turn abort handling: first Ctrl+C aborts the current turn and
 248:     // returns to the prompt; a second (at the idle prompt) exits.
 249:     const controller = new AbortController();
 250:     const onSigint = () => {
 251:       controller.abort("用户中断");
 252:     };
 253:     process.on("SIGINT", onSigint);
 254: 
 255:     // Run agent loop
 256:     const loop = agentLoop(
 257:       messages,
 258:       tools,
 259:       callModel,
 260:       modelConfig,
 261:       {
 262:         systemPrompt,
 263:         maxTurns: 50,
 264:         toolContext: {
 265:           workspaceRoot,
 266:           sessionId: sessionId!,
 267:           permissionMode,
 268:           modelConfig,
 269:         },
 270:         askUser,
 271:         abortSignal: controller.signal,
 272:       },
 273:     );
 274: 
 275:     let lastText = "";
 276:     let turnInputTokens = 0;
 277:     let turnOutputTokens = 0;
 278: 
 279:     for await (const event of loop) {
 280:       switch (event.type) {
 281:         case "text_delta":
 282:           process.stdout.write(event.delta);
 283:           lastText += event.delta;
 284:           break;
 285: 
 286:         case "tool_use":
 287:           console.log(`\n  🔧 Using tool: ${event.name}`);
 288:           break;
 289: 
 290:         case "tool_results":
 291:           for (const result of event.results) {
 292:             if (result.error) {
 293:               console.log(`  ❌ ${result.toolName}: ${result.error}`);
 294:             } else {
 295:               const preview = result.formatted.slice(0, 200);
 296:               console.log(`  ✅ ${result.toolName}: ${preview}...`);
 297:             }
 298:           }
 299:           // Auto-save after tool execution
 300:           persistence.save(sessionId!, messages).catch(() => {});
 301:           break;
 302: 
 303:         case "compacting":
 304:           console.log("\n  📦 Compacting context...");
 305:           break;
 306: 
 307:         case "usage":
 308:           turnInputTokens += event.usage.input_tokens;
 309:           turnOutputTokens += event.usage.output_tokens;
 310:           break;
 311: 
 312:         case "error":
 313:           console.error(`\n  ⚠️ Error:`, event.error);
 314:           break;
 315: 
 316:         case "done":
 317:           if (turnInputTokens || turnOutputTokens) {
 318:             console.log(
 319:               chalk.gray(
 320:                 `\n  [tokens: ${turnInputTokens} in / ${turnOutputTokens} out]`,
 321:               ),
 322:             );
 323:           }
 324:           // Final assistant text was added to messages in the loop
 325:           persistence.save(sessionId!, messages).catch(() => {});
 326:           break;
 327: 
 328:         case "aborted":
 329:           console.log(`\n  ⏹️ Aborted: ${event.reason}`);
 330:           break;
 331:       }
 332:     }
 333: 
 334:     // Detach this turn's SIGINT handler so handlers don't stack up.
 335:     process.removeListener("SIGINT", onSigint);
 336: 
 337:     console.log(""); // New line after response
 338:   }
 339: 
 340:   // Cleanup
 341:   rl.close();
 342:   await persistence.save(sessionId!, messages, { completed: true });
 343:   await mcpManager.disconnectAll();
 344:   console.log("\nGoodbye!");
 345: }
 346: 
 347: main().catch((error) => {
 348:   console.error("Fatal error:", error);
 349:   process.exit(1);
 350: });
