   1: // ============================================================
   2: // Agent Loop — The heart of the system
   3: // ============================================================
   4: 
   5: import type {
   6:   AskUserFn,
   7:   LoopEvent,
   8:   LoopOptions,
   9:   Message,
  10:   ModelCaller,
  11:   ModelConfig,
  12:   Tool,
  13:   ToolCall,
  14:   ToolContext,
  15:   ToolExecutionResult,
  16: } from "./types.js";
  17: import { checkPermission } from "./permissions.js";
  18: 
  19: // Default approver used when the caller (CLI) does not supply one — e.g.
  20: // sub-agents and tests. Preserves backward-compatible "allow" behavior;
  21: // plan-mode blocking is still enforced inside checkPermission().
  22: const defaultAskUser: AskUserFn = async () => true;
  23: 
  24: // --- Agent Loop (Async Generator) ---
  25: 
  26: export async function* agentLoop(
  27:   messages: Message[],
  28:   tools: Tool[],
  29:   callModel: ModelCaller,
  30:   modelConfig: ModelConfig,
  31:   options: LoopOptions,
  32: ): AsyncGenerator<LoopEvent> {
  33:   const {
  34:     maxTurns = 50,
  35:     autoCompactThreshold = 150_000,
  36:     systemPrompt,
  37:     abortSignal,
  38:     toolContext,
  39:     askUser = defaultAskUser,
  40:   } = options;
  41: 
  42:   // Build the full ToolContext from caller-provided values, falling back to
  43:   // sensible defaults. This replaces the previously hardcoded context.
  44:   const baseContext: ToolContext = {
  45:     workspaceRoot: toolContext?.workspaceRoot ?? process.cwd(),
  46:     sessionId: toolContext?.sessionId ?? "default",
  47:     permissionMode: toolContext?.permissionMode ?? "default",
  48:     modelConfig: toolContext?.modelConfig ?? modelConfig,
  49:   };
  50: 
  51:   let turnCount = 0;
  52:   let totalTokens = 0;
  53: 
  54:   while (turnCount < maxTurns) {
  55:     // Check for abort
  56:     if (abortSignal?.aborted) {
  57:       yield { type: "aborted", reason: abortSignal.reason };
  58:       return;
  59:     }
  60: 
  61:     // === STEP 1: Check if compaction is needed ===
  62:     if (estimateTokens(messages) > autoCompactThreshold) {
  63:       yield { type: "compacting" };
  64:       messages = await autoCompact(messages, callModel, modelConfig);
  65:       yield { type: "compacted", summary: "Context compressed" };
  66:     }
  67: 
  68:     // === STEP 2: Call the LLM ===
  69:     yield { type: "thinking" };
  70: 
  71:     let textBuffer = "";
  72:     const toolCalls: ToolCall[] = [];
  73:     let usage: { input_tokens: number; output_tokens: number } | null = null;
  74: 
  75:     try {
  76:       for await (const event of callModel(
  77:         messages,
  78:         tools,
  79:         systemPrompt,
  80:         modelConfig,
  81:       )) {
  82:         switch (event.type) {
  83:           case "text_delta":
  84:             textBuffer += event.delta;
  85:             yield { type: "text_delta", delta: event.delta };
  86:             break;
  87: 
  88:           case "tool_use":
  89:             toolCalls.push({
  90:               id: event.id,
  91:               type: "function",
  92:               function: {
  93:                 name: event.name,
  94:                 arguments: JSON.stringify(event.input),
  95:               },
  96:             });
  97:             yield {
  98:               type: "tool_use",
  99:               name: event.name,
 100:               input: event.input,
 101:             };
 102:             break;
 103: 
 104:           case "done":
 105:             usage = event.usage;
 106:             totalTokens += usage.input_tokens + usage.output_tokens;
 107:             yield { type: "usage", usage };
 108:             break;
 109: 
 110:           case "error":
 111:             // Handle recoverable errors
 112:             const recovery = await handleModelError(
 113:               event.error,
 114:               messages,
 115:               callModel,
 116:               modelConfig,
 117:             );
 118:             if (recovery === "retry") continue;
 119:             if (recovery === "abort") {
 120:               yield { type: "error", error: event.error };
 121:               return;
 122:             }
 123:             break;
 124:         }
 125:       }
 126:     } catch (error) {
 127:       yield { type: "error", error };
 128:       return;
 129:     }
 130: 
 131:     // === STEP 3: If no tool calls, we're done ===
 132:     if (toolCalls.length === 0) {
 133:       // Save the assistant's text response to message history
 134:       if (textBuffer) {
 135:         messages.push({
 136:           role: "assistant",
 137:           content: textBuffer,
 138:         });
 139:       }
 140:       yield {
 141:         type: "done",
 142:         finishReason: "end_turn",
 143:         turns: turnCount,
 144:       };
 145:       return;
 146:     }
 147: 
 148:     // === STEP 4: Add assistant message to history ===
 149:     messages.push({
 150:       role: "assistant",
 151:       content: textBuffer || null,
 152:       tool_calls: toolCalls,
 153:     });
 154: 
 155:     // === STEP 5: Execute tool calls (parallel for safe ones) ===
 156:     const toolResults = await executeToolCalls(
 157:       toolCalls,
 158:       tools,
 159:       baseContext,
 160:       askUser,
 161:       abortSignal,
 162:     );
 163: 
 164:     // === STEP 6: Add tool results to history ===
 165:     for (let i = 0; i < toolCalls.length; i++) {
 166:       messages.push({
 167:         role: "tool",
 168:         tool_call_id: toolCalls[i].id,
 169:         name: toolCalls[i].function.name,
 170:         content: toolResults[i].formatted,
 171:       });
 172:     }
 173: 
 174:     yield { type: "tool_results", results: toolResults };
 175: 
 176:     turnCount++;
 177:   }
 178: 
 179:   // Max turns reached
 180:   yield {
 181:     type: "done",
 182:     finishReason: "max_turns",
 183:     turns: turnCount,
 184:     message: "Maximum turns reached. Continue?",
 185:   };
 186: }
