 188: // --- Tool Call Execution ---
 189: 
 190: async function executeToolCalls(
 191:   toolCalls: ToolCall[],
 192:   tools: Tool[],
 193:   context: ToolContext,
 194:   askUser: AskUserFn,
 195:   abortSignal?: AbortSignal,
 196: ): Promise<ToolExecutionResult[]> {
 197:   // Separate into parallel-safe and serial groups
 198:   const parallelCalls: ToolCall[] = [];
 199:   const serialCalls: ToolCall[] = [];
 200: 
 201:   for (const call of toolCalls) {
 202:     const tool = tools.find((t) => t.name === call.function.name);
 203:     if (!tool) {
 204:       serialCalls.push(call);
 205:       continue;
 206:     }
 207:     if (tool.isConcurrencySafe()) {
 208:       parallelCalls.push(call);
 209:     } else {
 210:       serialCalls.push(call);
 211:     }
 212:   }
 213: 
 214:   const results: ToolExecutionResult[] = [];
 215: 
 216:   // Execute parallel-safe calls simultaneously
 217:   if (parallelCalls.length > 0) {
 218:     const parallelResults = await Promise.all(
 219:       parallelCalls.map((call) =>
 220:         executeSingleTool(call, tools, context, askUser),
 221:       ),
 222:     );
 223:     results.push(...parallelResults);
 224:   }
 225: 
 226:   // Execute serial calls one at a time
 227:   for (const call of serialCalls) {
 228:     // Allow long serial sequences to stop early on abort.
 229:     if (abortSignal?.aborted) {
 230:       results.push({
 231:         toolName: call.function.name,
 232:         error: "Aborted",
 233:         formatted: `Aborted before executing ${call.function.name}.`,
 234:       });
 235:       continue;
 236:     }
 237:     const result = await executeSingleTool(call, tools, context, askUser);
 238:     results.push(result);
 239:   }
 240: 
 241:   return results;
 242: }
 243: 
 244: async function executeSingleTool(
 245:   toolCall: ToolCall,
 246:   tools: Tool[],
 247:   context: ToolContext,
 248:   askUser: AskUserFn,
 249: ): Promise<ToolExecutionResult> {
 250:   const tool = tools.find((t) => t.name === toolCall.function.name);
 251: 
 252:   if (!tool) {
 253:     return {
 254:       toolName: toolCall.function.name,
 255:       error: `Unknown tool: ${toolCall.function.name}`,
 256:       formatted: `Error: Tool "${toolCall.function.name}" is not available.`,
 257:     };
 258:   }
 259: 
 260:   try {
 261:     let input: Record<string, unknown>;
 262:     try {
 263:       input = JSON.parse(toolCall.function.arguments);
 264:     } catch {
 265:       return {
 266:         toolName: tool.name,
 267:         error: "Invalid JSON arguments",
 268:         formatted: `Error: Failed to parse arguments for ${tool.name}`,
 269:       };
 270:     }
 271: 
 272:     // === Permission check (before any side effect) ===
 273:     const permission = await checkPermission(tool, input, context, {
 274:       askUser,
 275:     });
 276:     if (!permission.allowed) {
 277:       const reason = permission.reason ?? "denied by permission policy";
 278:       return {
 279:         toolName: tool.name,
 280:         error: reason,
 281:         formatted: `权限被拒绝: ${reason}`,
 282:       };
 283:     }
 284: 
 285:     const startTime = Date.now();
 286:     const result = await tool.call(input, context);
 287:     const duration = Date.now() - startTime;
 288: 
 289:     return {
 290:       toolName: tool.name,
 291:       result,
 292:       formatted: tool.formatResult({
 293:         ...result,
 294:         metadata: { ...result.metadata, durationMs: duration },
 295:       }),
 296:       durationMs: duration,
 297:     };
 298:   } catch (error) {
 299:     const message = error instanceof Error ? error.message : String(error);
 300:     return {
 301:       toolName: tool.name,
 302:       error: message,
 303:       formatted: `Error executing ${tool.name}: ${message}`,
 304:     };
 305:   }
 306: }
