 308: // --- Token Estimation (Simple Heuristic) ---
 309: 
 310: function estimateTokens(messages: Message[]): number {
 311:   let total = 0;
 312:   for (const msg of messages) {
 313:     switch (msg.role) {
 314:       case "user":
 315:         for (const block of msg.content) {
 316:           if (block.type === "text") total += block.text.length;
 317:         }
 318:         break;
 319:       case "assistant":
 320:         if (msg.content) total += msg.content.length;
 321:         if (msg.tool_calls) {
 322:           for (const tc of msg.tool_calls) {
 323:             total += tc.function.arguments.length + tc.function.name.length;
 324:           }
 325:         }
 326:         break;
 327:       case "tool":
 328:         total += msg.content.length;
 329:         break;
 330:       case "system":
 331:         total += msg.content.length;
 332:         break;
 333:     }
 334:   }
 335:   // Rough estimate: ~1 token per 4 characters
 336:   return Math.ceil(total / 4);
 337: }
