 339: // --- Auto-Compaction ---
 340: 
 341: async function autoCompact(
 342:   messages: Message[],
 343:   callModel: ModelCaller,
 344:   modelConfig: ModelConfig,
 345: ): Promise<Message[]> {
 346:   const TAIL_SIZE = 20;
 347:   const oldMessages = messages.slice(0, -TAIL_SIZE);
 348:   const tailMessages = messages.slice(-TAIL_SIZE);
 349: 
 350:   if (oldMessages.length === 0) return messages;
 351: 
 352:   // Summarize old messages
 353:   const summaryPrompt = `Summarize the conversation so far. Include:
 354: 1. What the user asked for (the main task)
 355: 2. Key decisions made
 356: 3. Files that were modified (with paths)
 357: 4. What still needs to be done
 358: 5. Any important context for continuing the work
 359: 
 360: Be concise but complete. This summary will replace the old messages
 361: so the conversation can continue with a fresh context window.`;
 362: 
 363:   const summaryMessages: Message[] = [
 364:     ...oldMessages,
 365:     { role: "user", content: [{ type: "text", text: summaryPrompt }] },
 366:   ];
 367: 
 368:   // Call model without tools for summarization
 369:   const chunks: string[] = [];
 370:   for await (const event of callModel(
 371:     summaryMessages,
 372:     [],
 373:     "You are a helpful assistant that summarizes conversations.",
 374:     modelConfig,
 375:   )) {
 376:     if (event.type === "text_delta") {
 377:       chunks.push(event.delta);
 378:     }
 379:   }
 380:   const summary = chunks.join("");
 381: 
 382:   // Rebuild: system summary + tail
 383:   return [
 384:     {
 385:       role: "system",
 386:       content: `[CONVERSATION SUMMARY]\n${summary}`,
 387:     },
 388:     ...tailMessages,
 389:   ];
 390: }
