 392: // --- Error Recovery ---
 393: 
 394: async function handleModelError(
 395:   error: unknown,
 396:   _messages: Message[],
 397:   _callModel: ModelCaller,
 398:   _modelConfig: ModelConfig,
 399: ): Promise<"retry" | "abort"> {
 400:   const err = error as any;
 401: 
 402:   // Rate limit → wait and retry
 403:   if (err?.status === 429) {
 404:     const delay = err?.retryAfter || 5000;
 405:     await sleep(delay);
 406:     return "retry";
 407:   }
 408: 
 409:   // Context too long → compact and retry
 410:   if (
 411:     err?.status === 400 &&
 412:     (err?.message?.includes("context_length") ||
 413:       err?.message?.includes("maximum context"))
 414:   ) {
 415:     return "retry";
 416:   }
 417: 
 418:   // Auth error → abort
 419:   if (err?.status === 401 || err?.status === 403) {
 420:     return "abort";
 421:   }
 422: 
 423:   // Unknown error → abort
 424:   return "abort";
 425: }
 426: 
 427: function sleep(ms: number): Promise<void> {
 428:   return new Promise((resolve) => setTimeout(resolve, ms));
 429: }
