 275:         description:
 276:           "The text to replace it with. Use empty string to delete.",
 277:       },
 278:     },
 279:     required: ["filePath", "old_string", "new_string"],
 280:   },
 281:   isReadOnly: false,
 282:   isConcurrencySafe: false, // Same file edits must be serial
