 302:       const content = fs.readFileSync(filePath, "utf-8");
 303:       const oldStr = input.old_string;
 304:       const newStr = input.new_string;
 305: 
 306:       // Count occurrences
 307:       let count = 0;
 308:       let pos = 0;
 309:       while ((pos = content.indexOf(oldStr, pos)) !== -1) {
 310:         count++;
 311:         pos += oldStr.length;
 312:       }
 313: 
 314:       if (count === 0) {
 315:         return {
 316:           content: "",
