 477:     required: ["pattern"],
 478:   },
 479:   isReadOnly: true,
 480:   isConcurrencySafe: true,
 481: 
 482:   async call(input, context): Promise<ToolResult> {
 483:     const searchDir = input.path
 484:       ? path.resolve(context.workspaceRoot, input.path)
 485:       : context.workspaceRoot;
 486: 
 487:     try {
 488:       const files = await fg(input.pattern, {
 489:         cwd: searchDir,
 490:         ignore: ["**/node_modules/**", "**/.git/**"],
 491:         absolute: false,
 492:         dot: false,
 493:       });
 494: 
 495:       const MAX_RESULTS = 500;
 496:       const truncated = files.length > MAX_RESULTS;
 497:       const resultFiles = files.slice(0, MAX_RESULTS);
 498:       // Sort for deterministic output
 499:       resultFiles.sort();
 500: 
 501:       const content =
 502:         resultFiles.length === 0
 503:           ? "No files found matching pattern."
 504:           : resultFiles.join("\n");
 505: 
 506:       return {
 507:         content,
 508:         truncated,
 509:         metadata: { linesRead: resultFiles.length },
 510:       };
 511:     } catch (error: any) {
 512:       return {
 513:         content: "",
 514:         error: `Error searching files: ${error.message}`,
 515:       };
 516:     }
 517:   },
 518: 
 519:   async checkPermissions(_input, _context) {
 520:     return { allowed: true }; // Read-only
 521:   },
 522: });
