 524: // ============================================================
 525: // Grep Tool
 526: // ============================================================
 527: 
 528: export const GrepTool: Tool = createTool<GrepInput>({
 529:   name: "grep",
 530:   description: "Search file contents with regex",
 531:   promptDescription:
 532:     "Search file contents with regex pattern. Uses ripgrep if available, falls back to Node.js.",
 533:   inputSchema: {
 534:     type: "object",
 535:     properties: {
 536:       pattern: {
 537:         type: "string",
 538:         description: "Regex pattern to search for",
 539:       },
 540:       path: {
 541:         type: "string",
 542:         description: "Directory or file to search (default: workspace root)",
 543:       },
 544:       include: {
 545:         type: "string",
 546:         description: "File pattern filter, e.g. '*.ts'",
 547:       },
 548:     },
 549:     required: ["pattern"],
 550:   },
 551:   isReadOnly: true,
 552:   isConcurrencySafe: true,
 553: 
 554:   async call(input, context): Promise<ToolResult> {
 555:     const searchDir = input.path
 556:       ? path.resolve(context.workspaceRoot, input.path)
 557:       : context.workspaceRoot;
 558: 
 559:     // Try ripgrep first, fall back to Node.js
 560:     try {
 561:       let cmd = `rg --line-number --no-heading --color never `;
 562: 
 563:       if (input.include) {
 564:         cmd += `--glob '${input.include}' `;
 565:       }
 566: 
 567:       // Ignore common directories
 568:       cmd += `--glob '!node_modules' --glob '!.git' `;
 569: 
 570:       // Escape the pattern for shell
 571:       const escaped = input.pattern.replace(/'/g, "'\\''");
 572:       cmd += `'${escaped}' '${searchDir}'`;
 573: 
 574:       const { stdout } = await execAsync(cmd, {
 575:         timeout: 30_000,
 576:         maxBuffer: 10 * 1024 * 1024,
 577:       });
 578: 
 579:       const lines = stdout.trim().split("\n").filter(Boolean);
 580:       const MAX_RESULTS = 250;
 581:       const truncated = lines.length > MAX_RESULTS;
 582: 
 583:       if (lines.length === 0) {
 584:         return { content: "No matches found." };
 585:       }
 586: 
 587:       return {
 588:         content: lines.slice(0, MAX_RESULTS).join("\n"),
 589:         truncated,
 590:         metadata: { linesRead: Math.min(lines.length, MAX_RESULTS) },
 591:       };
 592:     } catch (error: any) {
 593:       // rg not found or error — fall back
 594:       if (error.code === 1 && error.stdout === "") {
 595:         return { content: "No matches found." };
 596:       }
 597: 
 598:       try {
 599:         // Fallback: use fast-glob + manual regex search
 600:         const pattern = input.include || "**/*";
 601:         const files = await fg(pattern, {
 602:           cwd: searchDir,
 603:           ignore: ["**/node_modules/**", "**/.git/**"],
 604:           absolute: true,
 605:         });
 606: 
 607:         const results: string[] = [];
 608:         const regex = new RegExp(input.pattern, "gi");
 609: 
 610:         for (const file of files.slice(0, 100)) {
 611:           try {
 612:             const stat = fs.statSync(file);
 613:             if (stat.isDirectory() || stat.size > 1024 * 1024) continue;
 614: 
 615:             const content = fs.readFileSync(file, "utf-8");
 616:             const lines = content.split("\n");
 617:             for (let i = 0; i < lines.length; i++) {
 618:               if (regex.test(lines[i])) {
 619:                 const relPath = path.relative(context.workspaceRoot, file);
 620:                 results.push(`${relPath}:${i + 1}: ${lines[i].trim()}`);
 621:                 regex.lastIndex = 0; // Reset
 622:               }
 623:             }
 624:           } catch {
 625:             // Skip unreadable files
 626:           }
 627:         }
 628: 
 629:         const MAX_RESULTS = 250;
 630:         const truncated = results.length > MAX_RESULTS;
 631: 
 632:         if (results.length === 0) {
 633:           return { content: "No matches found." };
 634:         }
 635: 
 636:         return {
 637:           content: results.slice(0, MAX_RESULTS).join("\n"),
 638:           truncated,
 639:           metadata: { linesRead: Math.min(results.length, MAX_RESULTS) },
 640:         };
 641:       } catch (fallbackError: any) {
 642:         return {
 643:           content: "",
 644:           error: `Error searching: ${fallbackError.message}`,
 645:         };
 646:       }
 647:     }
 648:   },
 649: 
 650:   async checkPermissions(_input, _context) {
 651:     return { allowed: true }; // Read-only
 652:   },
 653: });
 654: 
 655: // ============================================================
 656: // Helpers
 657: // ============================================================
 658: 
 659: function isBinary(buffer: Buffer): boolean {
 660:   // Check first 8KB for null bytes (common binary indicator)
 661:   const sampleSize = Math.min(buffer.length, 8192);
 662:   for (let i = 0; i < sampleSize; i++) {
 663:     if (buffer[i] === 0) return true;
 664:   }
 665:   return false;
 666: }
 667: 
 668: function formatSize(bytes: number): string {
 669:   if (bytes < 1024) return `${bytes} B`;
 670:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
 671:   return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
 672: }
 673: 
 674: function generateSimpleDiff(oldStr: string, newStr: string): string {
 675:   const oldLines = oldStr.split("\n");
 676:   const newLines = newStr.split("\n");
 677: 
 678:   let diff = "";
 679:   for (const line of oldLines) {
 680:     if (!newLines.includes(line)) {
 681:       diff += `- ${line}\n`;
 682:     }
 683:   }
 684:   for (const line of newLines) {
 685:     if (!oldLines.includes(line)) {
 686:       diff += `+ ${line}\n`;
 687:     }
 688:   }
 689: 
 690:   return diff || "(whitespace-only change)";
 691: }
