  59:           if (block.type === "image") {
  60:             const url =
  61:               block.source.type === "base64"
  62:                 ? `data:${block.source.media_type};base64,${block.source.data}`
  63:                 : block.source.url!;
  64:             return {
  65:               type: "image_url",
  66:               image_url: { url },
  67:             } as const;
  68:           }
  69:           throw new Error(`Unknown content type: ${(block as any).type}`);
  70:         }),
  71:       };
  72: 
  73:     case "assistant":
  74:       return {
  75:         role: "assistant",
  76:         content: msg.content,
  77:         tool_calls: msg.tool_calls as any,
  78:       };
  79: 
  80:     case "tool":
  81:       return {
  82:         role: "tool",
  83:         tool_call_id: msg.tool_call_id,
  84:         content: msg.content,
  85:       };
  86: 
  87:     case "system":
  88:       return {
  89:         role: "system",
  90:         content: msg.content,
  91:       };
  92:   }
  93: }
  94: 
  95: // --- OpenAI-Compatible Streaming Caller ---
  96: 
  97: async function* openAICompatibleCaller(
  98:   messages: Message[],
  99:   tools: Tool[],
 100:   systemPrompt: string,
 101:   config: ModelConfig,
 102: ): AsyncGenerator<StreamEvent> {
 103:   const client = new OpenAI({
 104:     apiKey: config.apiKey,
 105:     baseURL:
 106:       config.baseURL ||
 107:       PROVIDER_CONFIGS[config.provider]?.baseURL ||
 108:       "https://api.openai.com/v1",
 109:   });
 110: 
 111:   const model =
 112:     config.model || PROVIDER_CONFIGS[config.provider]?.defaultModel || "gpt-4o";
 113: 
 114:   const requestMessages: OpenAI.Chat.Completions.ChatCompletionMessageParam[] =
 115:     [
 116:       { role: "system", content: systemPrompt },
 117:       ...messages.map(convertToOpenAIMessage),
 118:     ];
 119: 
 120:   const stream = await client.chat.completions.create({
 121:     model,
 122:     messages: requestMessages,
 123:     tools: tools.length > 0 ? formatToolsForOpenAI(tools) : undefined,
 124:     tool_choice: tools.length > 0 ? "auto" : undefined,
 125:     max_tokens: config.maxTokens,
 126:     temperature: config.temperature ?? 0.1,
 127:     stream: true,
 128:   });
 129: 
 130:   // Parse streaming response
 131:   const toolCallBuffers: Map<
 132:     number,
 133:     { id: string; name: string; arguments: string }
 134:   > = new Map();
 135: 
 136:   let usage = { input_tokens: 0, output_tokens: 0 };
 137: 
 138:   for await (const chunk of stream) {
 139:     const delta = chunk.choices[0]?.delta;
 140: 
 141:     // Text delta
 142:     if (delta?.content) {
 143:       yield { type: "text_delta", delta: delta.content };
 144:     }
 145: 
 146:     // Tool call delta
 147:     if (delta?.tool_calls) {
 148:       for (const tc of delta.tool_calls) {
 149:         if (!toolCallBuffers.has(tc.index)) {
 150:           toolCallBuffers.set(tc.index, {
 151:             id: tc.id || "",
 152:             name: tc.function?.name || "",
 153:             arguments: "",
 154:           });
 155:         }
 156:         const buf = toolCallBuffers.get(tc.index)!;
 157:         if (tc.id) buf.id = tc.id;
 158:         if (tc.function?.name) buf.name = tc.function.name;
 159:         if (tc.function?.arguments) buf.arguments += tc.function.arguments;
 160:       }
 161:     }
 162: 
 163:     // Usage
 164:     if (chunk.usage) {
 165:       usage = {
 166:         input_tokens: chunk.usage.prompt_tokens || 0,
 167:         output_tokens: chunk.usage.completion_tokens || 0,
 168:       };
 169:     }
 170: 
 171:     // Finish reason
 172:     if (chunk.choices[0]?.finish_reason) {
 173:       // Emit completed tool calls
 174:       for (const [, buf] of toolCallBuffers) {
 175:         try {
 176:           const input = JSON.parse(buf.arguments);
 177:           yield {
 178:             type: "tool_use",
 179:             id: buf.id,
 180:             name: buf.name,
 181:             input,
 182:           };
 183:         } catch {
 184:           yield {
 185:             type: "error",
 186:             error: new Error(
 187:               `Failed to parse tool arguments for "${buf.name}"`,
 188:             ),
 189:           };
 190:         }
 191:       }
 192: 
 193:       yield {
 194:         type: "done",
 195:         usage,
 196:         finish_reason: chunk.choices[0].finish_reason,
 197:       };
 198:     }
 199:   }
 200: }
 201: 
 202: // --- Format Tools for OpenAI ---
 203: 
 204: function formatToolsForOpenAI(tools: Tool[]): OpenAI.Chat.Completions.ChatCompletionTool[] {
 205:   return tools
 206:     .filter((t) => t.isEnabled())
 207:     .map((t) => ({
 208:       type: "function" as const,
 209:       function: {
 210:         name: t.name,
 211:         description: t.promptDescription,
 212:         parameters: t.inputSchema,
 213:       },
 214:     }));
 215: }
 216: 
 217: // --- Model Caller Factory ---
 218: 
 219: export function createModelCaller(cfg: ModelConfig): ModelCaller {
 220:   // All providers use OpenAI-compatible API for now
 221:   return openAICompatibleCaller;
 222: }
 223: 
 224: // --- Error Detection Helpers ---
 225: 
 226: export function isRateLimitError(error: any): boolean {
 227:   return error?.status === 429;
 228: }
 229: 
 230: export function isContextLengthError(error: any): boolean {
 231:   return (
 232:     error?.status === 400 &&
 233:     (error?.message?.includes("context_length") ||
 234:       error?.message?.includes("maximum context"))
 235:   );
 236: }
 237: 
 238: export function isAuthError(error: any): boolean {
 239:   return error?.status === 401 || error?.status === 403;
 240: }
 241: 
 242: export function isProviderError(error: any): boolean {
 243:   return error?.status >= 500;
 244: }
 245: 
 246: // --- Provider Resolution ---
 247: 
 248: export function resolveProviderConfig(
 249:   partial: Partial<ModelConfig> & { apiKey: string },
 250: ): ModelConfig {
 251:   const provider = partial.provider || "openai";
 252:   const defaults = PROVIDER_CONFIGS[provider] || PROVIDER_CONFIGS.custom;
 253: 
 254:   return {
 255:     provider,
 256:     model: partial.model || defaults.defaultModel,
 257:     apiKey: partial.apiKey,
 258:     baseURL: partial.baseURL || defaults.baseURL,
 259:     maxTokens: partial.maxTokens,
 260:     temperature: partial.temperature,
 261:     options: partial.options,
 262:   };
 263: }
 264: 
 265: export { PROVIDER_CONFIGS };
