   1: // ============================================================
   2: // Task Tool — Sub-agent system for complex multi-step tasks
   3: // ============================================================
   4: // Spawns an independent sub-agent with a limited tool set and
   5: // isolated context window. The sub-agent works autonomously
   6: // and returns a text summary of its findings.
   7: // ============================================================
   8: 
   9: import type { Tool, ToolContext, ToolResult, Message, LoopEvent } from "./types.js";
  10: import { createTool } from "./tool-registry.js";
  11: import { agentLoop } from "./agent-loop.js";
  12: import { createModelCaller } from "./llm-adapter.js";
  13: 
  14: // --- Constants ---
  15: 
  16: const SUBAGENT_MAX_TURNS = 10;
  17: const SUBAGENT_COMPACT_THRESHOLD = 50_000;
  18: 
  19: // --- Input ---
  20: 
  21: interface TaskInput {
  22:   description: string;
  23:   prompt: string;
  24:   subagent_name: string;
  25:   [key: string]: unknown;
  26: }
  27: 
  28: // --- Allowed sub-agent types ---
  29: 
  30: const ALLOWED_SUBAGENTS = ["code-explorer"];
  31: 
  32: // Lazy load sub-agent tools to break circular dependency with tools.ts
  33: // tools.ts imports TaskTool -> task-tool.ts imports tools classes -> cycle!
  34: let _subagentTools: Tool[] | null = null;
  35: async function getSubagentTools(): Promise<Tool[]> {
  36:   if (!_subagentTools) {
  37:     const { ReadTool, GlobTool, GrepTool, BashTool } = await import("./tools.js");
  38:     _subagentTools = [ReadTool, GlobTool, GrepTool, BashTool];
  39:   }
  40:   return _subagentTools;
  41: }
  42: 
  43: // --- Tool ---
  44: 
  45: export const TaskTool: Tool = createTool<TaskInput>({
  46:   name: "task",
  47:   description:
  48:     "Launch a sub-agent to handle complex, multi-step tasks autonomously",
  49:   promptDescription:
  50:     "Launch a sub-agent to handle complex, multi-step tasks. " +
  51:     'Provide description (short summary), prompt (detailed instructions), and subagent_name ("code-explorer"). ' +
  52:     "The sub-agent has access to Read, Glob, Grep, and Bash tools and works independently. " +
  53:     "Use this for broad code exploration, searching across many files, or research tasks " +
  54:     "where intermediate tool results don't need user review.",
  55:   inputSchema: {
  56:     type: "object",
  57:     properties: {
  58:       description: {
  59:         type: "string",
  60:         description: "A short (3-5 word) description of the task",
  61:       },
  62:       prompt: {
  63:         type: "string",
  64:         description:
  65:           "The detailed task for the sub-agent to perform. Be specific about what to find or do.",
  66:       },
  67:       subagent_name: {
  68:         type: "string",
  69:         description:
  70:           'The type of sub-agent. Currently only "code-explorer" is supported.',
  71:         enum: ["code-explorer"],
  72:         default: "code-explorer",
  73:       },
  74:     },
  75:     required: ["description", "prompt", "subagent_name"],
  76:   },
  77:   isReadOnly: false,
  78:   isConcurrencySafe: true,
  79: 
  80:   async call(input, context): Promise<ToolResult> {
  81:     const description = input.description?.trim();
  82:     const prompt = input.prompt?.trim();
  83:     const subagentName = input.subagent_name || "code-explorer";
  84: 
  85:     // --- Validation ---
  86: 
  87:     if (!description) {
  88:       return { content: "", error: "description is required" };
  89:     }
  90:     if (!prompt) {
  91:       return { content: "", error: "prompt is required" };
  92:     }
  93:     if (!ALLOWED_SUBAGENTS.includes(subagentName)) {
  94:       return {
  95:         content: "",
  96:         error: `Unknown subagent type: "${subagentName}". Allowed: ${ALLOWED_SUBAGENTS.join(", ")}`,
  97:       };
  98:     }
  99:     if (!context.modelConfig) {
 100:       return {
 101:         content: "",
 102:         error:
 103:           "Task tool requires modelConfig in context. The CLI must provide this.",
 104:       };
 105:     }
 106: 
 107:     // --- Setup sub-agent ---
 108: 
 109:     const subMessages: Message[] = [
 110:       {
 111:         role: "user",
 112:         content: [{ type: "text", text: prompt }],
 113:       },
 114:     ];
 115: 
 116:     const subCaller = createModelCaller(context.modelConfig);
 117: 
 118:     const subSystemPrompt = [
 119:       "You are a helpful sub-agent with access to read-only tools.",
 120:       `Your task: ${description}`,
 121:       "",
 122:       "Instructions:",
 123:       "- Use the available tools to complete your task",
 124:       "- Be thorough but efficient",
 125:       "- Your final response should be a clear summary of your findings",
 126:       "- Do not ask clarifying questions — work with what you have",
 127:       "- When you have gathered enough information, respond with your findings directly (no tool calls)",
 128:       "",
 129:       "Available tools:",
 130:       "- read: Read file contents with line numbers",
 131:       "- glob: Find files matching a pattern",
 132:       "- grep: Search file contents with regex",
 133:       "- bash: Execute shell commands (read-only operations only)",
 134:     ].join("\n");
 135: 
 136:     // --- Run sub-agent loop ---
 137: 
 138:     const startTime = Date.now();
 139:     const outputChunks: string[] = [];
 140:     let toolCallCount = 0;
 141:     let errorMessage: string | undefined;
 142: 
 143:     try {
 144:       const subagentTools = await getSubagentTools();
 145:       const loop = agentLoop(
 146:         subMessages,
 147:         subagentTools,
 148:         subCaller,
 149:         context.modelConfig,
 150:         {
 151:           systemPrompt: subSystemPrompt,
 152:           maxTurns: SUBAGENT_MAX_TURNS,
 153:           autoCompactThreshold: SUBAGENT_COMPACT_THRESHOLD,
 154:           // Run sub-agent tools in the same workspace/session as the parent.
 155:           toolContext: {
 156:             workspaceRoot: context.workspaceRoot,
 157:             sessionId: context.sessionId,
 158:             permissionMode: context.permissionMode,
 159:             modelConfig: context.modelConfig,
 160:           },
 161:         },
 162:       );
 163: 
 164:       for await (const event of loop) {
 165:         switch (event.type) {
 166:           case "text_delta":
 167:             outputChunks.push(event.delta);
 168:             break;
 169: 
 170:           case "tool_use":
 171:             toolCallCount++;
 172:             break;
 173: 
 174:           case "done":
 175:             // Sub-agent finished successfully
 176:             break;
 177: 
 178:           case "aborted":
 179:             errorMessage = event.reason;
 180:             break;
 181: 
 182:           case "error":
 183:             errorMessage = String(event.error);
 184:             break;
 185: 
 186:           case "thinking":
 187:           case "tool_results":
 188:           case "usage":
 189:           case "compacting":
 190:           case "compacted":
 191:             // Silent — sub-agent internals
 192:             break;
 193:         }
 194:       }
 195:     } catch (error: any) {
 196:       errorMessage = error.message || String(error);
 197:     }
 198: 
 199:     const duration = Date.now() - startTime;
 200:     const output = outputChunks.join("").trim();
 201: 
 202:     if (errorMessage && !output) {
 203:       return {
 204:         content: "",
 205:         error: `Sub-agent failed: ${errorMessage}`,
 206:         metadata: { durationMs: duration },
 207:       };
 208:     }
 209: 
 210:     const header = [
 211:       `[Sub-agent "${subagentName}" completed]`,
 212:       `Task: ${description}`,
 213:       `Tool calls: ${toolCallCount}`,
 214:       `Duration: ${(duration / 1000).toFixed(1)}s`,
 215:       ``,
 216:       `--- Findings ---`,
 217:       ``,
 218:     ].join("\n");
 219: 
 220:     return {
 221:       content: header + (output || "(no output)"),
 222:       truncated: false,
 223:       metadata: { durationMs: duration, linesRead: toolCallCount },
 224:     };
 225:   },
 226: 
 227:   async checkPermissions(_input, _context) {
 228:     return { allowed: true };
 229:     // Sub-agent uses read-only tools, so this is safe to auto-approve.
 230:     // The user explicitly requested the sub-agent via the task tool.
 231:   },
 232: });
 233: 
